import type { Lesson } from "@/lib/topics";

/** AP US History — one Lesson per CED topic across all 9 periods (105 topics). */

const KA = "https://www.khanacademy.org/humanities/us-history";

const U: Record<number, string> = {
  1: "Period 1: 1491-1607",
  2: "Period 2: 1607-1754",
  3: "Period 3: 1754-1800",
  4: "Period 4: 1800-1848",
  5: "Period 5: 1844-1877",
  6: "Period 6: 1865-1898",
  7: "Period 7: 1890-1945",
  8: "Period 8: 1945-1980",
  9: "Period 9: 1980-Present",
};

const mk = (
  unit: number,
  id: string,
  title: string,
  blurb: string,
  keyIdeas: string[],
  sampleProblem: string,
  sampleWalkthrough: string,
  flashcards: { q: string; a: string }[]
): Lesson => ({
  slug: `apush-${id.replace(".", "-")}`,
  title,
  courses: [{ courseSlug: "ap-us-history", unitNumber: unit, unitTitle: U[unit] }],
  blurb,
  keyIdeas,
  sampleProblem,
  sampleWalkthrough,
  flashcards,
  links: [{ title: "APUSH", url: KA, source: "Khan Academy" }],
});

